style.css:
@-moz-document domain("chat.openai.com"), domain("chatgpt.com") {
/* Background + base text */
  html, body {
    background-color: #ffe6f0 !important; /* pastel pink */
    color: #3a0030 !important;            /* deep plum text */
  }

  /* Chat containers / bubbles (broad selectors so it works across UI updates) */
  main, [data-testid="conversation-turn"] article, .prose, .markdown {
    background-color: #fff7fb !important; /* blush panel */
    border-radius: 18px !important;
    padding: 12px !important;
  }

  /* Sidebar + header */
  aside, header {
    background-color: #ffccdd !important;
    color: #3a0030 !important;
  }

  /* Buttons */
  button {
    background-color: #ff99cc !important;
    border: none !important;
    border-radius: 12px !important;
    color: #ffffff !important;
    font-weight: 600 !important;
  }
  button:hover {
    background-color: #ff66b2 !important;
  }

  /* Links */
  a {
    color: #cc0066 !important;
    font-weight: 600 !important;
  }
  a:hover {
    color: #ff3399 !important;
    text-decoration: underline !important;
  }
}
